     1	import type { AuthTokens, UserInfo } from './types';
     2	
     3	const STORAGE_KEY = 'webox.auth.v1';
     4	export const API_BASE = (import.meta.env.VITE_API_BASE_URL as string | undefined) ?? '/api/v1';
     5	
     6	interface Persisted {
     7	  refreshToken: string | null;
     8	  user: UserInfo | null;
     9	}
    10	
    11	let accessToken: string | null = null;
    12	let persist: Persisted = { refreshToken: null, user: null };
    13	let refreshPromise: Promise<boolean> | null = null;
    14	const listeners = new Set<() => void>();
    15	
    16	function load(): void {
    17	  try {
    18	    const raw = localStorage.getItem(STORAGE_KEY);
    19	    if (!raw) return;
    20	    const parsed = JSON.parse(raw) as Partial<Persisted>;
    21	    persist = {
    22	      refreshToken: typeof parsed.refreshToken === 'string' ? parsed.refreshToken : null,
    23	      user: parsed.user && typeof parsed.user === 'object' ? (parsed.user as UserInfo) : null,
    24	    };
    25	  } catch {
    26	    persist = { refreshToken: null, user: null };
    27	  }
    28	}
    29	
    30	function save(): void {
    31	  try {
    32	    localStorage.setItem(STORAGE_KEY, JSON.stringify(persist));
    33	  } catch {
    34	    /* storage unavailable: keep in memory */
    35	  }
    36	}
    37	
    38	function emit(): void {
    39	  listeners.forEach((fn) => fn());
    40	}
    41	
    42	load();
    43	
    44	export const session = {
    45	  getAccessToken: (): string | null => accessToken,
    46	  getRefreshToken: (): string | null => persist.refreshToken,
    47	  getUser: (): UserInfo | null => persist.user,
    48	  hasRefreshToken: (): boolean => Boolean(persist.refreshToken),
    49	  subscribe(fn: () => void): () => void {
    50	    listeners.add(fn);
    51	    return () => listeners.delete(fn);
    52	  },
    53	  setAuth(tokens: AuthTokens): void {
    54	    accessToken = tokens.accessToken;
    55	    persist = { refreshToken: tokens.refreshToken, user: tokens.user };
    56	    save();
    57	    emit();
    58	  },
    59	  setTokens(tokens: { accessToken: string; refreshToken?: string }): void {
    60	    accessToken = tokens.accessToken;
    61	    if (tokens.refreshToken) persist.refreshToken = tokens.refreshToken;
    62	    save();
    63	    emit();
    64	  },
    65	  setUser(user: UserInfo): void {
    66	    persist.user = user;
    67	    save();
    68	    emit();
    69	  },
    70	  clear(): void {
    71	    accessToken = null;
    72	    persist = { refreshToken: null, user: null };
    73	    try {
    74	      localStorage.removeItem(STORAGE_KEY);
    75	    } catch {
    76	      /* ignore */
    77	    }
    78	    emit();
    79	  },
    80	  /** Single-flight refresh. Returns true when a new access token is available. */
    81	  async refresh(): Promise<boolean> {
    82	    if (!persist.refreshToken) return false;
    83	    if (refreshPromise) return refreshPromise;
    84	    refreshPromise = (async () => {
    85	      try {
    86	        const res = await fetch(`${API_BASE}/auth/refresh`, {
    87	          method: 'POST',
    88	          headers: { 'Content-Type': 'application/json' },
    89	          body: JSON.stringify({ refreshToken: persist.refreshToken }),
    90	        });
    91	        if (!res.ok) return false;
    92	        const env = (await res.json()) as { code?: string; data?: { accessToken: string; refreshToken?: string } };
    93	        if (!env.data?.accessToken) return false;
    94	        session.setTokens({ accessToken: env.data.accessToken, refreshToken: env.data.refreshToken });
    95	        return true;
    96	      } catch {
    97	        return false;
    98	      } finally {
    99	        refreshPromise = null;
   100	      }
   101	    })();
   102	    return refreshPromise;
   103	  },
   104	};
