     1	import { API_BASE, session } from './session';
     2	
     3	export interface SseOptions {
     4	  method?: 'GET' | 'POST';
     5	  body?: unknown;
     6	  headers?: Record<string, string>;
     7	  signal: AbortSignal;
     8	  onEvent: (event: string, data: string) => void;
     9	}
    10	
    11	/** Consume an SSE endpoint using fetch + ReadableStream (Bearer auth). */
    12	export async function openSse(path: string, opts: SseOptions): Promise<void> {
    13	  const token = session.getAccessToken();
    14	  const headers: Record<string, string> = {
    15	    Accept: 'text/event-stream',
    16	    ...(opts.headers ?? {}),
    17	  };
    18	  if (token) headers['Authorization'] = `Bearer ${token}`;
    19	  if (opts.body !== undefined) headers['Content-Type'] = 'application/json';
    20	
    21	  const res = await fetch(`${API_BASE}${path}`, {
    22	    method: opts.method ?? 'GET',
    23	    headers,
    24	    body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
    25	    signal: opts.signal,
    26	  });
    27	
    28	  if (!res.ok) {
    29	    let code = `HTTP_${res.status}`;
    30	    try {
    31	      const env = (await res.json()) as { code?: string };
    32	      if (env.code) code = env.code;
    33	    } catch {
    34	      /* ignore */
    35	    }
    36	    const err = new Error(code) as Error & { code: string; status: number };
    37	    err.code = code;
    38	    err.status = res.status;
    39	    throw err;
    40	  }
    41	  if (!res.body) throw new Error('STREAM_UNSUPPORTED');
    42	
    43	  const reader = res.body.getReader();
    44	  const decoder = new TextDecoder();
    45	  let buffer = '';
    46	
    47	  const dispatch = (frame: string) => {
    48	    let event = 'message';
    49	    const dataLines: string[] = [];
    50	    for (const rawLine of frame.split(/\r?\n/)) {
    51	      if (!rawLine || rawLine.startsWith(':')) continue;
    52	      const idx = rawLine.indexOf(':');
    53	      const field = idx === -1 ? rawLine : rawLine.slice(0, idx);
    54	      let value = idx === -1 ? '' : rawLine.slice(idx + 1);
    55	      if (value.startsWith(' ')) value = value.slice(1);
    56	      if (field === 'event') event = value;
    57	      else if (field === 'data') dataLines.push(value);
    58	    }
    59	    if (dataLines.length > 0) opts.onEvent(event, dataLines.join('\n'));
    60	  };
    61	
    62	  try {
    63	    for (;;) {
    64	      const { done, value } = await reader.read();
    65	      if (done) break;
    66	      buffer += decoder.decode(value, { stream: true });
    67	      let idx: number;
    68	      while ((idx = buffer.indexOf('\n\n')) !== -1) {
    69	        const frame = buffer.slice(0, idx);
    70	        buffer = buffer.slice(idx + 2);
    71	        if (frame.trim()) dispatch(frame);
    72	      }
    73	    }
    74	    if (buffer.trim()) dispatch(buffer);
    75	  } finally {
    76	    try {
    77	      reader.releaseLock();
    78	    } catch {
    79	      /* ignore */
    80	    }
    81	  }
    82	}
    83	
    84	export function parseEventJson<T>(data: string): T | null {
    85	  try {
    86	    return JSON.parse(data) as T;
    87	  } catch {
    88	    return null;
    89	  }
    90	}

