     1	import { create } from 'zustand';
     2	import { api } from '../api/client';
     3	import { EP } from '../api/endpoints';
     4	import { session } from '../api/session';
     5	import type { AuthTokens, UserInfo } from '../api/types';
     6	
     7	type AuthStatus = 'loading' | 'anonymous' | 'authenticated';
     8	
     9	interface AuthState {
    10	  status: AuthStatus;
    11	  user: UserInfo | null;
    12	  login: (email: string, password: string) => Promise<UserInfo>;
    13	  register: (email: string, password: string, displayName?: string) => Promise<UserInfo>;
    14	  logout: () => Promise<void>;
    15	  bootstrap: () => Promise<void>;
    16	}
    17	
    18	export const useAuthStore = create<AuthState>((set, get) => ({
    19	  status: 'loading',
    20	  user: session.getUser(),
    21	
    22	  async login(email, password) {
    23	    const env = await api.post<AuthTokens>(EP.login, { email, password }, { auth: false });
    24	    session.setAuth(env.data);
    25	    set({ status: 'authenticated', user: env.data.user });
    26	    return env.data.user;
    27	  },
    28	
    29	  async register(email, password, displayName) {
    30	    await api.post<{ id: number; email: string; role: string }>(
    31	      EP.register,
    32	      { email, password, ...(displayName ? { displayName } : {}) },
    33	      { auth: false },
    34	    );
    35	    return get().login(email, password);
    36	  },
    37	
    38	  async logout() {
    39	    const rt = session.getRefreshToken();
    40	    if (rt) {
    41	      try {
    42	        await api.post(EP.logout, { refreshToken: rt });
    43	      } catch {
    44	        /* logout is best-effort */
    45	      }
    46	    }
    47	    session.clear();
    48	    set({ status: 'anonymous', user: null });
    49	  },
    50	
    51	  async bootstrap() {
    52	    if (!session.hasRefreshToken()) {
    53	      set({ status: 'anonymous', user: null });
    54	      return;
    55	    }
    56	    const ok = await session.refresh();
    57	    if (!ok) {
    58	      session.clear();
    59	      set({ status: 'anonymous', user: null });
    60	      return;
    61	    }
    62	    try {
    63	      const env = await api.get<UserInfo>(EP.me);
    64	      session.setUser(env.data);
    65	      set({ status: 'authenticated', user: env.data });
    66	    } catch {
    67	      session.clear();
    68	      set({ status: 'anonymous', user: null });
    69	    }
    70	  },
    71	}));
