    56	    typeof v.dishId === 'number' &&
    57	    typeof v.name === 'string' &&
    58	    typeof v.basePriceCents === 'number' &&
    59	    typeof v.unitPriceCents === 'number' &&
    60	    typeof v.qty === 'number' &&
    61	    v.qty > 0 &&
    62	    Array.isArray(v.options) &&
    63	    typeof v.lineId === 'string'
    64	  );
    65	};
