    11	export function useApiQuery<T>(path: string | null, deps: unknown[] = []) {
    12	  const [state, setState] = useState<QueryState<T>>({ data: null, loading: Boolean(path), error: null });
    13	  const [tick, setTick] = useState(0);
    14	  const key = JSON.stringify(deps);
    15	  const mounted = useRef(true);
    16	
    17	  useEffect(() => {
    18	    mounted.current = true;
    19	    return () => {
    20	      mounted.current = false;
    21	    };
    22	  }, []);
    23	
    24	  useEffect(() => {
    25	    if (!path) {
    26	      setState({ data: null, loading: false, error: null });
    27	      return;
    28	    }
    29	    const controller = new AbortController();
    30	    setState((s) => ({ ...s, loading: true, error: null }));
    31	    api
    32	      .get<T>(path, { signal: controller.signal })
    33	      .then((env) => {
    34	        if (!controller.signal.aborted) setState({ data: env.data, loading: false, error: null });
    35	      })
    36	      .catch((e) => {
    37	        if (controller.signal.aborted) return;
    38	        setState({ data: null, loading: false, error: e as ApiError });
    39	      });
    40	    return () => controller.abort();
    41	    // eslint-disable-next-line react-hooks/exhaustive-deps
    42	  }, [path, key, tick]);
    43	
    44	  const reload = useCallback(() => setTick((n) => n + 1), []);
    45	  return { ...state, reload };
