    10	/** Subscribe to /menu/stream; after 3 consecutive failures fall back to 5s polling. */
    11	export function useMenuStream(enabled: boolean): StockMode {
    12	  const [mode, setMode] = useState<StockMode>('off');
    13	
    14	  useEffect(() => {
    15	    if (!enabled) {
    16	      setMode('off');
    17	      return;
    18	    }
    19	    let stopped = false;
    20	    let failures = 0;
    21	    let controller: AbortController | null = null;
    22	    let pollTimer = 0;
    23	    let retryTimer = 0;
    24	
    25	    const store = useStockStore.getState();
    26	
    27	    const startPolling = () => {
    28	      if (stopped) return;
    29	      setMode('polling');
    30	      store.setLive(false);
    31	      const poll = async () => {
    32	        if (stopped) return;
    33	        try {
    34	          const env = await api.get<Paged<MenuItem>>(`${EP.menu}${`?page=1&size=100`}`);
    35	          for (const item of env.data.items) {
    36	            useStockStore.getState().setStock(item.dishId, item.availableQty);
    37	          }
    38	        } catch {
    39	          /* keep polling */
    40	        }
    41	        if (!stopped) pollTimer = window.setTimeout(poll, Number(import.meta.env.VITE_SSE_POLL_MS ?? 5000));
    42	      };
    43	      void poll();
    44	    };
    45	
    46	    const connect = async () => {
    47	      if (stopped) return;
    48	      controller = new AbortController();
    49	      try {
    50	        setMode('live');
    51	        store.setLive(true);
    52	        await openSse(EP.stream, {
    53	          signal: controller.signal,
    54	          onEvent: (event, data) => {
    55	            if (event === 'snapshot') {
    56	              const items = parseEventJson<StockEvent[]>(data);
    57	              if (Array.isArray(items)) useStockStore.getState().setSnapshot(items);
    58	            } else if (event === 'stock') {
    59	              const item = parseEventJson<StockEvent>(data);
    60	              if (item && typeof item.dishId === 'number') {
    61	                useStockStore.getState().setStock(item.dishId, item.available);
    62	              }
    63	            }
    64	          },
    65	        });
    66	        if (!stopped) {
    67	          failures += 1;
    68	          if (failures >= 3) startPolling();
    69	          else retryTimer = window.setTimeout(connect, 3000);
    70	        }
    71	      } catch {
    72	        if (stopped || controller.signal.aborted) return;
    73	        failures += 1;
    74	        if (failures >= 3) startPolling();
    75	        else retryTimer = window.setTimeout(connect, 3000);
    76	      }
    77	    };
    78	
    79	    void connect();
    80	
    81	    return () => {
    82	      stopped = true;
    83	      controller?.abort();
    84	      window.clearTimeout(pollTimer);
    85	      window.clearTimeout(retryTimer);
    86	      useStockStore.getState().setLive(false);
    87	    };
    88	  }, [enabled]);
    89	
    90	  return mode;
    91	}
