    43	const lineKey = (dishId: number, optionIds: number[]): string =>
    44	  `${dishId}|${[...optionIds].sort((a, b) => a - b).join(',')}`;
    45	
    46	let seq = 0;
    47	const nextLineId = (): string => {
    48	  seq += 1;
    49	  return `L${seq}-${Math.random().toString(36).slice(2, 8)}`;
    50	};
