    67	export const useCartStore = create<CartState>()(
    68	  persist(
    69	    (set, get) => ({
    70	      lines: [],
    71	
    72	      totalQty: () => get().lines.reduce((sum, l) => sum + l.qty, 0),
    73	      totalCents: () => get().lines.reduce((sum, l) => sum + l.unitPriceCents * l.qty, 0),
    74	
    75	      add(input, qty = 1) {
    76	        const currentQty = get().totalQty();
    77	        if (currentQty + qty > MAX_TOTAL_QTY) return 'limit';
    78	        const ids = input.options.map((o) => o.optionId);
    79	        const key = lineKey(input.dishId, ids);
    80	        const existing = get().lines.find((l) => l.lineId.startsWith(`${key}#`));
    81	        if (existing) {
    82	          if (currentQty + qty > MAX_TOTAL_QTY) return 'limit';
    83	          set((s) => ({
    84	            lines: s.lines.map((l) => (l.lineId === existing.lineId ? { ...l, qty: l.qty + qty } : l)),
    85	          }));
    86	          return 'added';
    87	        }
    88	        const unitPriceCents = input.options.reduce((sum, o) => sum + o.priceDeltaCents, input.basePriceCents);
    89	        const line: CartLine = {
    90	          lineId: `${key}#${nextLineId()}`,
    91	          dishId: input.dishId,
    92	          name: input.name,
    93	          imageUrl: input.imageUrl ?? null,
    94	          basePriceCents: input.basePriceCents,
    95	          options: [...input.options].sort((a, b) => a.optionId - b.optionId),
    96	          unitPriceCents,
    97	          qty,
    98	          addedAt: Date.now(),
    99	        };
   100	        set((s) => ({ lines: [...s.lines, line] }));
   101	        return 'added';
   102	      },
   103	
   104	      inc(lineId) {
   105	        if (get().totalQty() + 1 > MAX_TOTAL_QTY) return 'limit';
   106	        set((s) => ({ lines: s.lines.map((l) => (l.lineId === lineId ? { ...l, qty: l.qty + 1 } : l)) }));
   107	        return 'ok';
   108	      },
   109	
   110	      dec(lineId) {
   111	        const line = get().lines.find((l) => l.lineId === lineId);
   112	        if (!line) return;
   113	        if (line.qty <= 1) {
   114	          set((s) => ({ lines: s.lines.filter((l) => l.lineId !== lineId) }));
   115	        } else {
   116	          set((s) => ({ lines: s.lines.map((l) => (l.lineId === lineId ? { ...l, qty: l.qty - 1 } : l)) }));
   117	        }
   118	      },
   119	
   120	      remove(lineId) {
   121	        set((s) => ({ lines: s.lines.filter((l) => l.lineId !== lineId) }));
   122	      },
   123	
   124	      clear() {
   125	        set({ lines: [] });
   126	      },
   127	    }),
   128	    {
   129	      name: 'webox.cart.v1',
   130	      version: 1,
   131	      partialize: (s) => ({ lines: s.lines }),
   132	      merge: (persisted, current) => {
   133	        const raw = (persisted as { lines?: unknown })?.lines;
   134	        const lines = Array.isArray(raw) ? raw.filter(isValidLine) : [];
   135	        return { ...current, lines };
   136	      },
   137	    },
   138	  ),
   139	);
