    10	/** Stable key bound to a canonical request body: same body -> same key until reset. */
    11	export function useIdempotencyKey(canonicalBody: string) {
    12	  const ref = useRef<{ body: string; key: string } | null>(null);
    13	  if (!ref.current || ref.current.body !== canonicalBody) {
    14	    ref.current = { body: canonicalBody, key: uuid() };
    15	  }
    16	  const key = ref.current.key;
    17	  const reset = () => {
    18	    ref.current = null;
    19	  };
    20	  return { key, reset };
