     1	import { useState } from 'react';
     2	import { Link, NavLink, Outlet, useNavigate } from 'react-router-dom';
     3	import { t } from '../../i18n/en';
     4	import { useAuthStore, isAdmin } from '../../store/authStore';
     5	import { useCartStore } from '../../store/cartStore';
     6	import { formatMoney } from '../../utils/money';
     7	
     8	export function AppLayout() {
     9	  const user = useAuthStore((s) => s.user);
    10	  const logout = useAuthStore((s) => s.logout);
    11	  const qty = useCartStore((s) => s.lines.reduce((sum, l) => sum + l.qty, 0));
    12	  const total = useCartStore((s) => s.lines.reduce((sum, l) => sum + l.unitPriceCents * l.qty, 0));
    13	  const [navOpen, setNavOpen] = useState(false);
    14	  const navigate = useNavigate();
    15	
    16	  const handleLogout = async () => {
    17	    await logout();
    18	    navigate('/login', { replace: true });
    19	  };
    20	
    21	  const links = (
    22	    <>
    23	      <NavLink to="/menu" className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`} onClick={() => setNavOpen(false)}>
    24	        {t('nav.menu')}
    25	      </NavLink>
    26	      <NavLink to="/orders" className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`} onClick={() => setNavOpen(false)}>
    27	        {t('nav.orders')}
    28	      </NavLink>
    29	      <NavLink to="/preferences" className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`} onClick={() => setNavOpen(false)}>
    30	        {t('nav.preferences')}
    31	      </NavLink>
    32	      <NavLink to="/cart" className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`} onClick={() => setNavOpen(false)} data-testid="nav-cart">
    33	        {t('nav.cart')}
    34	        {qty > 0 ? <span className="nav-badge">{qty}</span> : null}
    35	      </NavLink>
    36	      {isAdmin(user) ? (
    37	        <NavLink to="/admin" className={({ isActive }) => `nav-link${isActive ? ' active' : ''}`} onClick={() => setNavOpen(false)}>
    38	          {t('nav.console')}
    39	        </NavLink>
    40	      ) : null}
    41	    </>
    42	  );
    43	
    44	  return (
    45	    <>
    46	      <header className="topbar">
    47	        <div className="topbar-inner">
    48	          <Link to="/menu" className="brand" aria-label="WeBox home">
    49	            <span className="brand-mark" aria-hidden="true">WB</span>
    50	            <span>WeBox</span>
    51	          </Link>
    52	          <nav className={`nav${navOpen ? ' open' : ''}`} aria-label="Main navigation">
    53	            {links}
    54	          </nav>
    55	          <div className="topbar-user">
    56	            <span data-testid="current-user">{user?.email}</span>
    57	            <button type="button" className="btn btn-sm btn-outline" onClick={handleLogout} data-testid="logout">
    58	              {t('nav.logout')}
    59	            </button>
    60	          </div>
    61	          <button
    62	            type="button"
    63	            className="btn btn-sm btn-outline mobile-menu-btn"
    64	            aria-label="Toggle navigation"
    65	            aria-expanded={navOpen}
    66	            onClick={() => setNavOpen((v) => !v)}
    67	          >
    68	            ☰
    69	          </button>
    70	        </div>
    71	      </header>
    72	      <main className="main">
    73	        <Outlet />
    74	      </main>
    75	      {qty > 0 ? (
    76	        <div className="bottom-bar">
    77	          <div>
    78	            <div className="small muted">{qty} item{qty > 1 ? 's' : ''}</div>
    79	            <div className="price tabular" data-testid="bottom-bar-total">{formatMoney(total)}</div>
    80	          </div>
    81	          <Link to="/cart" className="btn btn-primary">
    82	            {t('nav.cart')}
    83	          </Link>
    84	        </div>
    85	      ) : null}
    86	    </>
    87	  );
    88	}
