    13	
    14	export function Modal({ open, onClose, title, children, footer, large, drawer }: ModalProps) {
    15	  useEffect(() => {
    16	    if (!open) return;
    17	    const onKey = (e: KeyboardEvent) => {
    18	      if (e.key === 'Escape') onClose();
    19	    };
    20	    document.addEventListener('keydown', onKey);
    21	    const prev = document.body.style.overflow;
    22	    document.body.style.overflow = 'hidden';
    23	    return () => {
    24	      document.removeEventListener('keydown', onKey);
    25	      document.body.style.overflow = prev;
    26	    };
    27	  }, [open, onClose]);
    28	
    29	  if (!open) return null;
    30	  return createPortal(
    31	    <div className={drawer ? 'overlay drawer-overlay' : 'overlay'} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
    32	      <div
    33	        className={drawer ? 'drawer' : `modal${large ? ' modal-lg' : ''}`}
