   203	              {(preview?.items ?? []).map((item, idx) => (
   204	                <div className="order-item" key={`${item.dishName}-${idx}`}>
   205	                  <div>
   206	                    <div style={{ fontWeight: 600 }}>{item.dishName} × {item.qty}</div>
   207	                    {item.options.length > 0 ? (
   208	                      <div className="small muted">
   209	                        {item.options.map((o) => `${o.name}${o.priceDeltaCents ? ` (+${formatMoney(o.priceDeltaCents)})` : ''}`).join(' · ')}
   210	                      </div>
   211	                    ) : null}
   212	                  </div>
   213	                  <span className="tabular">{formatMoney(item.subtotalCents)}</span>
   214	                </div>
   215	              ))}
   216	              {!preview ? (
   217	                items.map((it, idx) => {
   218	                  const line = lines[idx];
   219	                  return line ? (
   220	                    <div className="order-item" key={`${it.dishId}-${idx}`}>
   221	                      <div>
   222	                        <div style={{ fontWeight: 600 }}>{line.name} × {line.qty}</div>
   223	                        {line.options.length > 0 ? (
   224	                          <div className="small muted">{line.options.map((o) => o.name).join(' · ')}</div>
   225	                        ) : null}
   226	                      </div>
   227	                      <span className="tabular">{formatMoney(line.unitPriceCents * line.qty)}</span>
   228	                    </div>
   229	                  ) : null;
   230	                })
   231	              ) : null}
   232	            </div>
   233	          </section>
   234	
   235	          <section className="card card-pad stack-sm">
   236	            <h2 style={{ fontSize: 17 }}>Delivery</h2>
   237	            <div className="form-grid">
   238	              <div className="field">
   239	                <label className="label" htmlFor="checkout-date">{t('checkout.deliveryDate')}</label>
   240	                <select
   241	                  id="checkout-date"
   242	                  className="select"
   243	                  value={date}
   244	                  onChange={(e) => setDate(e.target.value)}
   245	                  data-testid="checkout-date"
   246	                >
   247	                  {(filters.data?.dates ?? []).map((d) => (
   248	                    <option key={d.date} value={d.date}>
   249	                      {d.date}{d.published ? '' : ' (not published)'}
   250	                    </option>
   251	                  ))}
   252	                  {!filters.data?.dates?.length ? <option value={date}>{date || '—'}</option> : null}
   253	                </select>
   254	              </div>
   255	              <div className="field">
   256	                <label className="label" htmlFor="checkout-meal">{t('checkout.mealType')}</label>
   257	                <select
   258	                  id="checkout-meal"
   259	                  className="select"
   260	                  value={meal}
   261	                  onChange={(e) => setMeal(e.target.value === 'Dinner' ? 'Dinner' : 'Lunch')}
   262	                  data-testid="checkout-meal"
   263	                >
   264	                  <option value="Lunch">{t('checkout.lunch')}</option>
   265	                  <option value="Dinner">{t('checkout.dinner')}</option>
   266	                </select>
   267	              </div>
   268	            </div>
   269	
   270	            <div className="field">
   271	              <label className="label" htmlFor="checkout-address">{t('checkout.address')}</label>
   272	              {addressBook.data && addressBook.data.length > 0 ? (
   273	                <div className="address-list">
   274	                  {addressBook.data.map((a) => (
   275	                    <label key={a.id} className={`address-option${selectedAddressId === a.id ? ' on' : ''}`}>
   276	                      <input
   277	                        type="radio"
   278	                        name="saved-address"
   279	                        checked={selectedAddressId === a.id}
   280	                        onChange={() => {
   281	                          setSelectedAddressId(a.id);
   282	                          setAddress(a.address);
   283	                        }}
   284	                      />
   285	                      <span>{a.address}</span>
   286	                    </label>
   287	                  ))}
   288	                  <label className={`address-option${selectedAddressId === null ? ' on' : ''}`}>
   289	                    <input
   290	                      type="radio"
   291	                      name="saved-address"
   292	                      checked={selectedAddressId === null}
   293	                      onChange={() => {
   294	                        setSelectedAddressId(null);
   295	                        setAddress('');
   296	                      }}
   297	                    />
   298	                    <span>{t('checkout.newAddress')}</span>
   299	                  </label>
   300	                </div>
   301	              ) : null}
   302	              <input
   303	                id="checkout-address"
   304	                className="input"
   305	                maxLength={MAX_ADDRESS}
   306	                value={address}
   307	                placeholder="e.g. Building A, 12F"
   308	                onChange={(e) => setAddress(e.target.value.slice(0, MAX_ADDRESS))}
   309	                data-testid="checkout-address"
   310	                aria-invalid={submitCode === 'VALIDATION_ADDRESS_LENGTH'}
   311	              />
   312	              <span className="hint">{address.length}/{MAX_ADDRESS}</span>
   313	              {selectedAddressId === null ? (
   314	                <label className="check-row">
   315	                  <input type="checkbox" checked={saveAddress} onChange={(e) => setSaveAddress(e.target.checked)} />
   316	                  {t('checkout.saveAddress')}
   317	                </label>
   318	              ) : null}
   319	            </div>
   320	          </section>
   321	        </div>
   322	
   323	        <aside className="card card-pad summary">
   324	          <h2 style={{ fontSize: 17, marginBottom: 10 }}>Summary</h2>
   325	
   326	          {previewLoading ? <Spinner label={t('common.loading')} /> : null}
   327	          {previewError ? <div className="banner banner-danger" role="alert">{previewError}</div> : null}
   328	
   329	          {preview?.autoSwitched ? (
   330	            <div className="banner banner-info" data-testid="auto-switch-banner" style={{ marginBottom: 10 }}>
   331	              {t('checkout.autoSwitched', {
   332	                meal: meal,
   333	                effectiveMeal: preview.effectiveMeal,
   334	                date: preview.effectiveDate,
   335	                cutoff: formatTime(preview.cutoffAt),
   336	              })}
   337	            </div>
   338	          ) : null}
   339	
   340	          {priceChanged ? (
   341	            <div className="banner banner-warn" style={{ marginBottom: 10 }} data-testid="price-changed">
   342	              {t('cart.priceUpdated', { total: formatMoney(preview?.totalCents ?? cartTotal) })}
   343	            </div>
   344	          ) : null}
   345	
   346	          {showBudget ? (
   347	            <div className="banner banner-warn" data-testid="budget-warning" style={{ marginBottom: 10 }}>
   348	              {t('checkout.budgetExceeded', {
   349	                budget: budgetMax > 0 ? formatMoney(budgetMax) : 'your budget',
   350	              })}
   351	            </div>
   352	          ) : null}
   353	
   354	          {stockIssues.length > 0 ? (
   355	            <div className="banner banner-danger" style={{ marginBottom: 10 }} data-testid="stock-issues">
   356	              <div className="stack-sm">
   357	                {stockIssues.map((s) => {
   358	                  const line = lines.find((l) => l.dishId === s.dishId);
   359	                  return (
   360	                    <span key={s.dishId}>
   361	                      {t('checkout.stockInsufficient', { available: s.available, dish: line?.name ?? `#${s.dishId}` })}
   362	                    </span>
   363	                  );
   364	                })}
   365	                <Link to="/cart" className="btn btn-outline btn-sm">{t('checkout.adjustCart')}</Link>
   366	              </div>
   367	            </div>
   368	          ) : null}
   369	
   370	          {existingOrderId ? (
   371	            <div className="banner banner-info" style={{ marginBottom: 10 }}>
   372	              An active order already exists for this meal.{' '}
   373	              <Link to={`/orders/${existingOrderId}`} className="btn btn-outline btn-sm" data-testid="checkout-existing-order">
   374	                {t('checkout.viewExistingOrder')}
   375	              </Link>
   376	            </div>
   377	          ) : null}
   378	
   379	          <div className="summary-row"><span className="muted">Items</span><span className="tabular">{preview?.itemCount ?? lines.reduce((n, l) => n + l.qty, 0)}</span></div>
   380	          <div className="summary-row"><span className="muted">{t('cart.subtotal')}</span><span className="tabular">{formatMoney(preview?.totalCents ?? cartTotal)}</span></div>
   381	          {preview ? (
   382	            <div className="summary-row"><span className="muted">{t('checkout.cutoff', { time: formatTime(preview.cutoffAt) })}</span><span className="tabular">{formatTime(preview.cutoffAt)}</span></div>
   383	          ) : null}
   384	          <div className="summary-row summary-total">
   385	            <span>{t('cart.total')}</span>
   386	            <span className="tabular" data-testid="checkout-total">{formatMoney(preview?.totalCents ?? cartTotal)}</span>
   387	          </div>
   388	
   389	          {submitError ? (
   390	            <div className="banner banner-danger" role="alert" data-testid="checkout-error" data-error-code={submitCode} style={{ marginTop: 10 }}>
   391	              {submitError}
   392	            </div>
   393	          ) : null}
   394	
   395	          {existingOrderId ? (
   396	            <Link to={`/orders/${existingOrderId}`} className="btn btn-primary btn-block" style={{ marginTop: 12 }}>
   397	              {t('checkout.viewExistingOrder')}
   398	            </Link>
   399	          ) : (
   400	            <button
   401	              type="button"
   402	              className="btn btn-primary btn-block"
   403	              style={{ marginTop: 12 }}
   404	              onClick={() => void submit()}
   405	              disabled={submitting || previewLoading || Boolean(previewError) || rateLimited > 0}
   406	              data-testid="checkout-submit"
   407	            >
   408	              {submitting ? t('checkout.placing') : rateLimited > 0 ? `${t('error.rateLimited')} (${rateLimited}s)` : t('checkout.placeOrder')}
   409	            </button>
   410	          )}
   411	          <p className="hint" style={{ marginTop: 10 }}>
   412	            {preview?.effectiveDate ? `${preview.effectiveMeal} · ${preview.effectiveDate}` : 'Stock is reserved only when the order is placed.'}
   413	          </p>
   414	        </aside>
   415	      </div>
   416	    </div>
   417	  );
   418	}

