1	import { useEffect, useMemo, useState } from 'react';
2	import { Link, useNavigate, useParams } from 'react-router-dom';
3	import { t } from '../../i18n/en';
4	import { EP } from '../../api/endpoints';
5	import type { DishDetail, OptionGroup } from '../../api/types';
6	import { useApiQuery } from '../../hooks/useApiQuery';
7	import { usePrefsStore } from '../../store/prefsStore';
8	import { useCartStore } from '../../store/cartStore';
9	import { useStockStore } from '../../store/stockStore';
10	import { notify } from '../../store/uiStore';
11	import { formatMoney } from '../../utils/money';
12	import { resolveImage } from '../../utils/image';
13	import { ImageWithFallback } from '../../components/ui/ImageWithFallback';
14	import { Modal } from '../../components/ui/Modal';
15	import { ErrorState, Spinner } from '../../components/ui/Feedback';
16	import { api } from '../../api/client';
17	
18	export function DishDetailPage() {
19	  const { dishId } = useParams();
20	  const id = Number(dishId);
21	  const navigate = useNavigate();
22	  const dish = useApiQuery<DishDetail>(Number.isFinite(id) ? EP.dish(id) : null, [id]);
23	  const prefs = usePrefsStore((s) => s.prefs);
24	  const setPrefs = usePrefsStore((s) => s.setPrefs);
25	  const add = useCartStore((s) => s.add);
26	  const totalQty = useCartStore((s) => s.lines.reduce((sum, l) => sum + l.qty, 0));
27	  const stockOverride = useStockStore((s) => (Number.isFinite(id) ? s.available[id] : undefined));
28	
29	  const [selected, setSelected] = useState<Record<number, number[]>>({});
30	  const [allergenOpen, setAllergenOpen] = useState(false);
31	  const [busy, setBusy] = useState(false);
32	
33	  useEffect(() => {
34	    if (!prefs) {
35	      api
36	        .get<typeof prefs>(EP.prefs)
37	        .then((env) => setPrefs(env.data))
38	        .catch(() => undefined);
39	    }
40	  }, [prefs, setPrefs]);
41	
42	  const groups = dish.data?.optionGroups ?? [];
43	  const chosenOptions = useMemo(() => {
44	    if (!dish.data) return [];
45	    const out: { optionId: number; name: string; priceDeltaCents: number }[] = [];
46	    for (const group of dish.data.optionGroups) {
47	      for (const optId of selected[group.groupId] ?? []) {
48	        const opt = group.options.find((o) => o.optionId === optId);
49	        if (opt) out.push({ optionId: opt.optionId, name: opt.name, priceDeltaCents: opt.priceDeltaCents });
50	      }
51	    }
52	    return out;
53	  }, [dish.data, selected]);
54	
55	  const missingGroups = useMemo(
56	    () =>
57	      groups
58	        .filter((g) => g.required && (selected[g.groupId]?.length ?? 0) < Math.max(1, g.minSelect))
59	        .map((g) => g.name),
60	    [groups, selected],
61	  );
62	
63	  const soldOut = dish.data
64	    ? typeof stockOverride === 'number'
65	      ? stockOverride <= 0
66	      : !dish.data.available
67	    : false;
68	  const availableQty = typeof stockOverride === 'number' ? stockOverride : dish.data?.availableQty ?? 0;
69	  const unitPriceCents = (dish.data?.priceCents ?? 0) + chosenOptions.reduce((sum, o) => sum + o.priceDeltaCents, 0);
70	
71	  const toggleOption = (group: OptionGroup, optionId: number) => {
72	    setSelected((prev) => {
73	      const current = prev[group.groupId] ?? [];
74	      if (group.maxSelect === 1) return { ...prev, [group.groupId]: [optionId] };
75	      if (current.includes(optionId)) return { ...prev, [group.groupId]: current.filter((x) => x !== optionId) };
76	      if (current.length >= group.maxSelect) return prev;
77	      return { ...prev, [group.groupId]: [...current, optionId] };
78	    });
79	  };
80	
81	  const doAdd = () => {
82	    if (!dish.data) return;
83	    const result = add({
84	      dishId: dish.data.dishId,
85	      name: dish.data.name,
86	      imageUrl: dish.data.imageUrl,
87	      basePriceCents: dish.data.priceCents,
88	      options: chosenOptions,
89	    });
90	    if (result === 'limit') notify.raw(t('menu.orderLimit'), 'ORDER_LIMIT_EXCEEDED');
91	    else notify.success(t('menu.added'));
92	    setAllergenOpen(false);
93	    window.setTimeout(() => setBusy(false), 300);
94	  };
95	
96	  const handleAdd = () => {
97	    if (!dish.data || busy || soldOut) return;
98	    if (totalQty >= 5) {
99	      notify.raw(t('menu.orderLimit'), 'ORDER_LIMIT_EXCEEDED');
100	      return;
101	    }
102	    if (missingGroups.length > 0) {
103	      notify.raw(t('detail.pleaseSelect', { groups: missingGroups.join(', ') }), 'VALIDATION_OPTION_REQUIRED');
104	      return;
105	    }
106	    setBusy(true);
107	    const flagged = (prefs?.allergens ?? []).filter((a) => (dish.data?.allergens ?? []).includes(a));
108	    if (flagged.length > 0) {
109	      setAllergenOpen(true);
110	      return;
111	    }
112	    doAdd();
113	  };
114	
115	  if (dish.loading) {
116	    return (
117	      <div className="stack">
118	        <div className="skeleton" style={{ height: 28, width: 180 }} />
119	        <div className="detail-grid">
120	          <div className="skeleton" style={{ aspectRatio: '4 / 3', borderRadius: 14 }} />
121	          <div className="stack-sm">
122	            <div className="skeleton" style={{ height: 60 }} />
123	            <div className="skeleton" style={{ height: 120 }} />
124	          </div>
125	        </div>
126	      </div>
127	    );
128	  }
129	  if (dish.error || !dish.data) return <ErrorState error={dish.error} onRetry={dish.reload} />;
130	
131	  const d = dish.data;
132	  return (
133	    <div data-testid="dish-detail">
134	      <div className="row small" style={{ marginBottom: 14 }}>
135	        <Link to="/menu">← {t('nav.menu')}</Link>
136	      </div>
137	      <div className="detail-grid">
138	        <div className="detail-media">
139	          <ImageWithFallback src={resolveImage(d.imageUrl)} alt={d.name} eager />
140	        </div>
141	        <div className="stack">
142	          <div>
143	            <div className="row-wrap" style={{ marginBottom: 8 }}>
144	              <span className="badge">{d.category}</span>
145	              <span className="badge badge-orange">{d.spiceLevel}</span>
146	              {soldOut ? <span className="badge badge-red">{t('menu.soldOut')}</span> : availableQty <= 3 ? <span className="badge badge-orange">{t('menu.onlyLeft', { count: availableQty })}</span> : null}
147	            </div>
148	            <h1 style={{ fontSize: 28 }}>{d.name}</h1>
149	            <p className="muted" style={{ marginTop: 8 }}>{d.description}</p>
150	            <div className="price price-lg tabular" style={{ marginTop: 12 }} data-testid="dish-price">
151	              {formatMoney(unitPriceCents)}
152	            </div>
153	          </div>
154	
155	          {d.optionGroups.map((group) => {
156	            const chosen = selected[group.groupId] ?? [];
157	            return (
158	              <fieldset key={group.groupId} className="option-group" style={{ border: 0, padding: 0, margin: 0 }} data-testid={`option-group-${group.groupId}`}>
159	                <div className="option-group-head">
160	                  <div>
161	                    <span style={{ fontWeight: 700 }}>{group.name}</span>{' '}
162	                    <span className={`badge ${group.required ? 'badge-orange' : ''}`}>
163	                      {group.required ? t('detail.required') : t('detail.optional')}
164	                    </span>
165	                  </div>
166	                  {group.maxSelect > 1 ? <span className="hint">{t('detail.selectUpTo', { count: group.maxSelect })}</span> : null}
167	                </div>
168	                <div className="stack-sm">
169	                  {group.options.map((opt) => {
170	                    const on = chosen.includes(opt.optionId);
171	                    return (
172	                      <label key={opt.optionId} className={`option-row${on ? ' on' : ''}`}>
173	                        <input
174	                          type={group.maxSelect === 1 ? 'radio' : 'checkbox'}
175	                          name={`group-${group.groupId}`}
176	                          checked={on}
177	                          disabled={!on && group.maxSelect > 1 && chosen.length >= group.maxSelect}
178	                          onChange={() => toggleOption(group, opt.optionId)}
179	                          data-testid={`option-${opt.optionId}`}
180	                        />
181	                        <span>{opt.name}</span>
182	                        {opt.priceDeltaCents !== 0 ? (
183	                          <span className="option-delta">+{formatMoney(opt.priceDeltaCents)}</span>
184	                        ) : null}
185	                      </label>
186	                    );
187	                  })}
188	                </div>
189	              </fieldset>
190	            );
191	          })}
192	
193	          <div className="row-wrap small muted">
194	            {d.protein ? <span><strong>{t('detail.protein')}:</strong> {d.protein}</span> : null}
195	            {d.allergens.length > 0 ? (
196	              <span><strong>{t('detail.allergens')}:</strong> {d.allergens.join(', ')}</span>
197	            ) : null}
198	          </div>
199	
200	          {missingGroups.length > 0 ? (
201	            <p className="hint">{t('detail.pleaseSelect', { groups: missingGroups.join(', ') })}</p>
202	          ) : null}
203	
204	          <div className="detail-footer">
205	            <div className="row" style={{ justifyContent: 'space-between' }}>
206	              <div>
207	                <div className="small muted">{t('cart.total')}</div>
208	                <div className="price tabular">{formatMoney(unitPriceCents)}</div>
209	              </div>
210	              <button
211	                type="button"
212	                className="btn btn-primary"
213	                onClick={handleAdd}
214	                disabled={soldOut || busy || missingGroups.length > 0}
215	                data-testid="detail-add-to-cart"
216	              >
217	                {soldOut ? t('menu.soldOut') : busy ? t('common.loading') : t('detail.addToCart')}
218	              </button>
219	            </div>
220	          </div>
221	        </div>
222	      </div>
223	
224	      <Modal open={allergenOpen} onClose={() => { setAllergenOpen(false); setBusy(false); }} title={t('allergen.title')}>
225	        <div data-testid="allergen-modal" className="stack-sm">
226	          <p>
227	            {t('allergen.message', {
228	              allergens: (prefs?.allergens ?? []).filter((a) => d.allergens.includes(a)).join(', '),
229	            })}
230	          </p>
231	        </div>
232	        <div className="modal-foot">
233	          <button type="button" className="btn btn-outline" onClick={() => { setAllergenOpen(false); setBusy(false); }}>
234	            {t('common.cancel')}
235	          </button>
236	          <button type="button" className="btn btn-primary" onClick={doAdd} data-testid="allergen-add-anyway">
237	            {t('allergen.addAnyway')}
238	          </button>
239	        </div>
240	      </Modal>
241	    </div>
242	  );
243	}
