import { useState } from 'react';
import { t } from '../../i18n/en';
import { EP } from '../../api/endpoints';
import { api } from '../../api/client';
import type { ReconcileResult } from '../../api/types';
import { useApiQuery } from '../../hooks/useApiQuery';
import { notify } from '../../store/uiStore';
import { ErrorState, SkeletonRows } from '../../components/ui/Feedback';
import { ConfirmReasonModal } from '../../components/console/ConfirmReasonModal';

const today = (): string => {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

export function InventoryPage() {
  const [date, setDate] = useState(today());
  const [dishId, setDishId] = useState('');
  const [delta, setDelta] = useState('');
  const [adjustOpen, setAdjustOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const result = useApiQuery<ReconcileResult>(`${EP.reconcile}?date=${encodeURIComponent(date)}`, [date]);

  const submitAdjust = async (reason: string) => {
    setBusy(true);
    try {
      await api.post(EP.adjust, {
        dishId: Number(dishId),
        serveDate: date,
        delta: Number(delta),
        confirm: true,
        reason,
      });
      notify.success('Stock adjusted.');
      setAdjustOpen(false);
      setDishId('');
      setDelta('');
      result.reload();
    } catch (e) {
      notify.error(e);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <div className="console-top">
        <div>
          <h1 style={{ fontSize: 23 }}>{t('console.inventory')}</h1>
          <p className="page-sub">Compare book availability against the inventory ledger.</p>
        </div>
      </div>

      <div className="card card-pad console-toolbar" style={{ marginBottom: 16 }}>
        <div className="field">
          <label className="label" htmlFor="inv-date">{t('console.date')}</label>
          <input id="inv-date" type="date" className="input" value={date} onChange={(e) => setDate(e.target.value)} />
        </div>
        <button type="button" className="btn btn-primary" onClick={result.reload} data-testid="inventory-drift">
          {t('console.reconcile')}
        </button>
      </div>

      {result.loading ? (
        <SkeletonRows />
      ) : result.error ? (
        <ErrorState error={result.error} onRetry={result.reload} />
      ) : result.data ? (
        <div className="card card-pad stack-sm" data-testid="reconcile-result">
          <div className="row" style={{ justifyContent: 'space-between' }}>
            <span className="muted small">Checked {result.data.checked} dishes on {result.data.date}</span>
            <span className={`badge ${result.data.drift.length ? 'badge-red' : 'badge-green'}`}>
              {result.data.drift.length ? `${result.data.drift.length} drift` : t('console.driftZero')}
            </span>
          </div>
          {result.data.drift.length > 0 ? (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr><th>Dish ID</th><th>Book available</th><th>Ledger derived</th><th>Drift</th></tr>
                </thead>
                <tbody>
                  {result.data.drift.map((row) => (
                    <tr key={row.dishId} className="drift-row">
                      <td>{row.dishId}</td>
                      <td>{row.bookAvailable}</td>
                      <td>{row.ledgerDerived}</td>
                      <td>{row.bookAvailable - row.ledgerDerived}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : null}
        </div>
      ) : null}

      <section className="card card-pad" style={{ marginTop: 18 }}>
        <h2 style={{ fontSize: 17, marginBottom: 12 }}>{t('console.adjust')}</h2>
        <div className="form-grid">
          <div className="field">
            <label className="label" htmlFor="inv-dish">Dish ID</label>
            <input id="inv-dish" className="input tabular" inputMode="numeric" value={dishId} onChange={(e) => setDishId(e.target.value)} />
          </div>
          <div className="field">
            <label className="label" htmlFor="inv-delta">{t('console.delta')} (+/−)</label>
            <input id="inv-delta" className="input tabular" inputMode="numeric" value={delta} onChange={(e) => setDelta(e.target.value)} />
          </div>
        </div>
        <button
          type="button"
          className="btn btn-outline"
          style={{ marginTop: 14 }}
          disabled={!dishId || !delta || !Number.isInteger(Number(delta))}
          onClick={() => setAdjustOpen(true)}
          data-testid="inventory-adjust"
        >
          {t('console.adjust')}
        </button>
      </section>

      <ConfirmReasonModal
        open={adjustOpen}
        title={t('console.adjust')}
        description={`Adjust dish #${dishId} stock by ${delta} on ${date}. This writes an inventory ledger entry and an audit record.`}
        onClose={() => setAdjustOpen(false)}
        onConfirm={(reason) => void submitAdjust(reason)}
        busy={busy}
        confirmLabel={t('console.adjust')}
      />
    </div>
  );
}

import { useEffect } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { t } from '../../i18n/en';
import { EP } from '../../api/endpoints';
import type { DashboardData } from '../../api/types';
import { useApiQuery } from '../../hooks/useApiQuery';
import { formatMoney } from '../../utils/money';
import { ErrorState, SkeletonRows } from '../../components/ui/Feedback';

export function DashboardPage() {
  const dashboard = useApiQuery<DashboardData>(EP.dashboard, []);

  useEffect(() => {
    const timer = window.setInterval(() => {
      if (document.visibilityState === 'visible') dashboard.reload();
    }, 60000);
    return () => window.clearInterval(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (dashboard.loading) return <SkeletonRows count={4} />;
  if (dashboard.error) return <ErrorState error={dashboard.error} onRetry={dashboard.reload} />;
  if (!dashboard.data) return null;
  const d = dashboard.data;

  const topData = d.topDishes.map((x) => ({ name: x.name, sold: x.soldQty }));
  const mealData = [{ name: 'Meals', Lunch: d.mealSplit.lunch, Dinner: d.mealSplit.dinner }];
  const trendData = d.trend.map((x) => ({ date: x.date, orders: x.orders, revenue: Math.round(x.revenueCents / 100) }));

  return (
    <div>
      <div className="console-top">
        <div>
          <h1 style={{ fontSize: 23 }}>{t('console.dashboard')}</h1>
          <p className="page-sub">Counts exclude cancelled orders · low stock is 0–3 available.</p>
        </div>
        <button type="button" className="btn btn-outline btn-sm" onClick={dashboard.reload} data-testid="dashboard-refresh">
          {t('console.refresh')}
        </button>
      </div>

      <div className="tiles" data-testid="dashboard-tiles">
        <div className="card tile">
          <div className="tile-label">{t('console.todayOrders')}</div>
          <div className="tile-value" data-testid="tile-orders">{d.today.orders}</div>
        </div>
        <div className="card tile">
          <div className="tile-label">{t('console.todayRevenue')}</div>
          <div className="tile-value">{formatMoney(d.today.revenueCents)}</div>
        </div>
        <div className="card tile">
          <div className="tile-label">{t('console.completed')}</div>
          <div className="tile-value">{d.today.completed}</div>
        </div>
        <div className="card tile">
          <div className="tile-label">{t('console.pending')}</div>
          <div className="tile-value">{d.today.pending}</div>
        </div>
        <div className="card tile">
          <div className="tile-label">{t('console.cancelled')}</div>
          <div className="tile-value">{d.today.cancelled}</div>
        </div>
      </div>

      <div className="chart-grid" style={{ marginTop: 18 }}>
        <section className="card chart-card">
          <div className="chart-title">{t('console.topDishes')}</div>
          <div className="chart-note">Sold quantity, cancelled excluded.</div>
          {topData.length === 0 ? (
            <p className="muted small" style={{ padding: '30px 0' }}>{t('console.noData')}</p>
          ) : (
            <ResponsiveContainer width="100%" height={260}>
              <BarChart data={topData} margin={{ top: 8, right: 8, left: -18, bottom: 36 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{ fontSize: 11 }} interval={0} angle={-20} textAnchor="end" height={56} />
                <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
                <Tooltip />
                <Bar dataKey="sold" fill="#0f766e" radius={[5, 5, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </section>

        <section className="card chart-card">
          <div className="chart-title">{t('console.mealSplit')}</div>
          <div className="chart-note">Non-cancelled orders.</div>
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={mealData} margin={{ top: 8, right: 8, left: -18, bottom: 8 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="name" tick={{ fontSize: 11 }} />
              <YAxis tick={{ fontSize: 11 }} allowDecimals={false} />
              <Tooltip />
              <Bar dataKey="Lunch" fill="#0f766e" radius={[5, 5, 0, 0]} />
              <Bar dataKey="Dinner" fill="#f59e0b" radius={[5, 5, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </section>
      </div>

      <div className="chart-grid" style={{ marginTop: 18 }}>
        <section className="card chart-card" data-testid="dashboard-trend">
          <div className="chart-title">{t('console.trend')}</div>
          <div className="chart-note">Orders and revenue (¥) per day.</div>
          <ResponsiveContainer width="100%" height={240}>
            <LineChart data={trendData} margin={{ top: 8, right: 12, left: -18, bottom: 8 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="date" tick={{ fontSize: 11 }} />
              <YAxis yAxisId="left" tick={{ fontSize: 11 }} allowDecimals={false} />
              <YAxis yAxisId="right" orientation="right" tick={{ fontSize: 11 }} />
              <Tooltip />
              <Line yAxisId="left" type="monotone" dataKey="orders" stroke="#0f766e" strokeWidth={2} dot={false} />
              <Line yAxisId="right" type="monotone" dataKey="revenue" stroke="#f59e0b" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </section>

        <section className="card card-pad" data-testid="dashboard-lowstock">
          <div className="chart-title">{t('console.lowStock')}</div>
          <div className="chart-note">0 ≤ available ≤ 3.</div>
          {d.lowStock.length === 0 ? (
            <p className="muted small" style={{ padding: '22px 0' }}>No low-stock dishes.</p>
          ) : (
            <div className="stack-sm" style={{ marginTop: 10 }}>
              {d.lowStock.map((x) => (
                <div className="row" key={x.dishId} style={{ justifyContent: 'space-between' }}>
                  <span>{x.name}</span>
                  <span className="badge badge-orange">{x.available} left</span>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

