import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { t } from '../../i18n/en';
import { EP } from '../../api/endpoints';
import { openSse, parseEventJson } from '../../api/sse';
import type { MealType } from '../../api/types';
import { Modal } from '../ui/Modal';
import { formatMoney } from '../../utils/money';
import { resolveImage } from '../../utils/image';
import { ImageWithFallback } from '../ui/ImageWithFallback';
import { MAX_PROMPT } from '../../utils/validation';

interface AiDish {
  dishId: number;
  name: string;
  priceCents: number;
  priceDisplay?: string;
  category: string;
  available: boolean | number;
  imageUrl?: string | null;
}

interface Props {
  open: boolean;
  onClose: () => void;
}

const QUICK = [
  { key: 'ai.quick.light', text: 'Something light' },
  { key: 'ai.quick.protein', text: 'High protein' },
  { key: 'ai.quick.notYesterday', text: 'Not what I had yesterday' },
  { key: 'ai.quick.spicy', text: 'Something spicy' },
];

const SESSION_KEY = 'webox.ai.session';

function getSessionId(): string {
  try {
    const existing = sessionStorage.getItem(SESSION_KEY);
    if (existing) return existing;
    const id = (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Math.random())).slice(0, 36);
    sessionStorage.setItem(SESSION_KEY, id);
    return id;
  } catch {
    return '';
  }
}

export function AiAssistant({ open, onClose }: Props) {
  const [prompt, setPrompt] = useState('');
  const [dishes, setDishes] = useState<AiDish[]>([]);
  const [reasons, setReasons] = useState<Record<number, string>>({});
  const [fallback, setFallback] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const controllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    if (!open) {
      controllerRef.current?.abort();
      controllerRef.current = null;
      setLoading(false);
    }
  }, [open]);

  const run = async (text: string) => {
    if (loading) return;
    const trimmed = text.trim();
    if (!trimmed) return;
    if (trimmed.length > MAX_PROMPT) {
      setError(t('ai.promptTooLong'));
      return;
    }
    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;
    setLoading(true);
    setError('');
    setDishes([]);
    setReasons({});
    setFallback(false);
    let timedOut = false;
    const timer = window.setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, Number(import.meta.env.VITE_AI_TIMEOUT_MS ?? 25000));

    try {
      await openSse(EP.aiRecommend, {
        method: 'POST',
        body: { prompt: trimmed, sessionId: getSessionId() },
        signal: controller.signal,
        onEvent: (event, data) => {
          if (event === 'meta') {
            const meta = parseEventJson<{ fallback?: boolean; sessionId?: string; model?: string }>(data);
            if (meta?.fallback) setFallback(true);
            if (meta?.sessionId) {
              try {
                sessionStorage.setItem(SESSION_KEY, meta.sessionId);
              } catch {
                /* ignore */
              }
            }
          } else if (event === 'dish') {
            const dish = parseEventJson<AiDish>(data);
            if (dish && typeof dish.dishId === 'number') {
              setDishes((prev) => (prev.some((d) => d.dishId === dish.dishId) ? prev : [...prev, dish]));
            }
          } else if (event === 'reason') {
            const payload = parseEventJson<{ dishId: number; text: string }>(data);
            if (payload) setReasons((prev) => ({ ...prev, [payload.dishId]: payload.text }));
          } else if (event === 'done') {
            setLoading(false);
          }
        },
      });
      setLoading(false);
    } catch (e) {
      if (timedOut) setError(t('ai.timeout'));
      else if (controller.signal.aborted) return;
      else {
        const err = e as { status?: number };
        setError(err.status === 429 ? t('ai.rateLimited') : t('ai.offline'));
      }
      setLoading(false);
    } finally {
      window.clearTimeout(timer);
    }
  };

  return (
    <Modal open={open} onClose={onClose} title={t('ai.title')} drawer>
      <div className="stack-sm">
        <p className="muted small">Describe what you feel like eating. Recommendations respect your allergies and stock.</p>
        <div className="field">
          <label className="label" htmlFor="ai-input">{t('ai.placeholder')}</label>
          <textarea
            id="ai-input"
            className="textarea"
            maxLength={MAX_PROMPT}
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder={t('ai.placeholder')}
            data-testid="ai-input"
          />
          <span className="hint">{prompt.length} / {MAX_PROMPT}</span>
        </div>
        <div className="ai-quick">
          {QUICK.map((q) => (
            <button key={q.key} type="button" onClick={() => { setPrompt(q.text); void run(q.text); }}>
              {t(q.key)}
            </button>
          ))}
        </div>
        <button
          type="button"
          className="btn btn-primary"
          disabled={loading || !prompt.trim()}
          onClick={() => void run(prompt)}
          data-testid="ai-send"
        >
          {loading ? t('ai.thinking') : t('ai.send')}
        </button>
        {fallback ? (
          <span className="badge badge-orange" data-testid="ai-fallback-badge">{t('ai.fallback')}</span>
        ) : null}
        {error ? (
          <div className="banner banner-danger" role="alert" data-testid="ai-error">{error}</div>
        ) : null}
        {loading ? (
          <div className="ai-thinking">
            <span className="spinner" aria-hidden="true" />
            {t('ai.thinking')}
          </div>
        ) : null}
        <div className="stack-sm" aria-live="polite">
          {dishes.map((dish) => (
            <div key={dish.dishId} className="ai-card" data-testid={`ai-card-${dish.dishId}`}>
              <div className="row" style={{ alignItems: 'flex-start' }}>
                <ImageWithFallback
                  src={resolveImage(dish.imageUrl ?? null)}
                  alt={dish.name}
                  className="cart-thumb"
                />
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 650 }}>{dish.name}</div>
                  <div className="row small" style={{ gap: 8, marginTop: 4 }}>
                    <span className="badge">{dish.category}</span>
                    <span className="price" style={{ fontSize: 15 }}>{formatMoney(dish.priceCents)}</span>
                  </div>
                </div>
              </div>
              {reasons[dish.dishId] ? (
                <div className="ai-reason" data-testid={`ai-reason-${dish.dishId}`}>{reasons[dish.dishId]}</div>
              ) : null}
              <Link to={`/dishes/${dish.dishId}`} className="btn btn-outline btn-sm" onClick={onClose}>
                {t('ai.addToCart')}
              </Link>
            </div>
          ))}
          {!loading && !error && dishes.length === 0 && prompt ? (
            <div className="empty-state" style={{ padding: '24px 10px' }}>
              <p className="muted small">{t('ai.empty')}</p>
            </div>
          ) : null}
        </div>
      </div>
    </Modal>
  );
}

import { useState } from 'react';
import { t } from '../../i18n/en';
import { EP } from '../../api/endpoints';
import { pageQuery } from '../../api/client';
import type { AuditRow, Paged } from '../../api/types';
import { useApiQuery } from '../../hooks/useApiQuery';
import { formatDateTime } from '../../utils/datetime';
import { EmptyState, ErrorState, SkeletonRows } from '../../components/ui/Feedback';
import { Pagination } from '../../components/ui/Pagination';

export function AuditPage() {
  const [action, setAction] = useState('');
  const [objectType, setObjectType] = useState('');
  const [page, setPage] = useState(1);
  const path = `${EP.audit}${pageQuery({ page, size: 20, action: action || undefined, objectType: objectType || undefined })}`;
  const logs = useApiQuery<Paged<AuditRow>>(path, [path]);
  const items = logs.data?.items ?? [];

  const apply = () => {
    setPage(1);
    logs.reload();
  };

  return (
    <div>
      <div className="console-top">
        <div>
          <h1 style={{ fontSize: 23 }}>{t('console.audit')}</h1>
          <p className="page-sub">Every high-risk action is recorded with before/after values.</p>
        </div>
      </div>

      <div className="card card-pad console-toolbar" style={{ marginBottom: 16 }}>
        <div className="field">
          <label className="label" htmlFor="audit-action">{t('console.auditAction')}</label>
          <input
            id="audit-action"
            className="input"
            value={action}
            onChange={(e) => setAction(e.target.value)}
            placeholder="e.g. DISH_UPDATE"
            data-testid="audit-filter-action"
          />
        </div>
        <div className="field">
          <label className="label" htmlFor="audit-object">{t('console.auditObject')}</label>
          <input id="audit-object" className="input" value={objectType} onChange={(e) => setObjectType(e.target.value)} placeholder="e.g. DISH" />
        </div>
        <button type="button" className="btn btn-primary" onClick={apply}>{t('console.apply')}</button>
      </div>

      {logs.loading ? (
        <SkeletonRows />
      ) : logs.error ? (
        <ErrorState error={logs.error} onRetry={logs.reload} />
      ) : items.length === 0 ? (
        <div className="card"><EmptyState title="No audit records." /></div>
      ) : (
        <div className="card table-wrap">
          <table className="console-table-cards" data-testid="audit-table">
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>{t('console.auditAction')}</th>
                <th>{t('console.auditObject')}</th>
                <th>{t('console.reason')}</th>
                <th>IP</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {items.map((row, idx) => (
                <tr key={row.id ?? idx}>
                  <td data-label="Time" className="small tabular">{formatDateTime(row.createdAt)}</td>
                  <td data-label="Actor" className="small">{row.actorEmail ?? row.actorId ?? '—'}</td>
                  <td data-label={t('console.auditAction')}><span className="badge">{row.action ?? '—'}</span></td>
                  <td data-label={t('console.auditObject')} className="small">{row.objectType ?? '—'} {row.objectId ?? ''}</td>
                  <td data-label={t('console.reason')} className="small">{row.reason ?? '—'}</td>
                  <td data-label="IP" className="small">{row.ip ?? '—'}</td>
                  <td data-label="Details">
                    <details>
                      <summary className="small">before / after</summary>
                      <div className="small muted" style={{ marginTop: 6 }}>{t('console.before')}</div>
                      <pre className="pre-json">{JSON.stringify(row.before ?? null, null, 2)}</pre>
                      <div className="small muted">{t('console.after')}</div>
                      <pre className="pre-json">{JSON.stringify(row.after ?? null, null, 2)}</pre>
                    </details>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <Pagination page={page} size={20} total={logs.data?.total ?? 0} onChange={setPage} />
    </div>
  );
}

