content.content:
.ai-reason { font-size: 12.5px; color: var(--ink-2); background: var(--surface-2); border-radius: 8px; padding: 8px 10px; }
.ai-thinking { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 13px; padding: 14px 0; }
.spinner { width: 16px; height: 16px; border: 2px solid var(--line); border-top-color: var(--primary); border-radius: 50%; animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- responsive ---------- */
@media (max-width: 1023px) {
  .detail-grid { grid-template-columns: 1fr; }
  .detail-media { position: static; }
  .console-shell { grid-template-columns: 190px 1fr; }
  .cart-layout { grid-template-columns: 1fr; }
  .summary { position: static; }
}
@media (max-width: 767px) {
  .topbar-inner { padding: 0 14px; gap: 10px; }
  .nav { display: none; }
  .nav.open {
    display: flex; position: absolute; top: var(--header-h); left: 0; right: 0;
    background: var(--ink); padding: 10px 14px 14px; flex-direction: column; align-items: stretch; gap: 2px;
    border-top: 1px solid rgba(255,255,255,.1);
  }
  .nav.open .nav-link { padding: 12px; font-size: 15px; }
  .mobile-menu-btn { display: inline-flex; margin-left: auto; }
  .topbar-user { display: none; }
  .main { padding: 18px 14px 104px; }
  .page-head h1 { font-size: 22px; }
  .dish-grid { grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; }
  .dish-media { aspect-ratio: 1 / 1; }
  .dish-body { padding: 11px 12px 12px; gap: 6px; }
  .dish-name { font-size: 14.5px; }
  .dish-desc { display: none; }
  .price { font-size: 16px; }
  .dish-foot { flex-direction: column; align-items: stretch; gap: 8px; }
  .dish-foot .btn { width: 100%; min-height: 40px; }
  .bottom-bar {
    display: flex; position: fixed; left: 0; right: 0; bottom: 0; z-index: 35;
    background: rgba(255,255,255,.97); border-top: 1px solid var(--line);
    padding: 10px 14px calc(10px + env(safe-area-inset-bottom)); gap: 12px; align-items: center;
    box-shadow: 0 -4px 16px rgba(15,23,42,.06);
  }
  .bottom-bar .btn { flex: 1; }
  .form-grid { grid-template-columns: 1fr; }
  .chart-grid { grid-template-columns: 1fr; }
  .console-shell { grid-template-columns: 1fr; }
  .console-side {
    position: fixed; left: 0; top: 0; bottom: 0; width: 236px; z-index: 50;
    transform: translateX(-100%); transition: transform .2s ease; height: 100vh;
  }
  .console-side.open { transform: none; }
  .console-main { padding: 16px 14px 80px; }
  .console-mobile-bar { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; }
  .console-table-cards thead { display: none; }
  .console-table-cards, .console-table-cards tbody, .console-table-cards tr, .console-table-cards td { display: block; width: 100%; }
  .console-table-cards tr { border: 1px solid var(--line); border-radius: 10px; margin-bottom: 10px; padding: 6px 10px; background: #fff; }
  .console-table-cards td { border: 0; padding: 6px 2px; display: flex; justify-content: space-between; gap: 14px; }
  .console-table-cards td::before { content: attr(data-label); color: var(--muted); font-size: 11.5px; text-transform: uppercase; letter-spacing: .04em; font-weight: 650; }
  .toast-stack { right: 12px; left: 12px; bottom: 78px; max-width: none; }
  .ai-fab { right: 14px; bottom: 84px; }
  .order-card { padding: 14px; }
  .kv { grid-template-columns: 1fr; gap: 3px 0; }
  .kv dd { margin-bottom: 8px; }
  .modal { padding: 18px; }
  .drawer { max-width: 100%; }
  .table-wrap { background: #fff; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }
}

/* topbar dark-surface button contrast */
.topbar .btn-outline { color: #f8fafc; border-color: rgba(255,255,255,.34); background: rgba(255,255,255,.04); }
.topbar .btn-outline:hover { background: rgba(255,255,255,.14); }

@media (max-width: 1023px) {
  .topbar-inner { gap: 12px; padding: 0 14px; }
  .topbar-user span { display: none; }
  .nav-link { padding: 8px 8px; font-size: 13.5px; }
}

.console-side .btn-outline { color: #f8fafc; border-color: rgba(255,255,255,.34); background: rgba(255,255,255,.04); }
.console-side .btn-outline:hover { background: rgba(255,255,255,.14); }

.btn.mobile-menu-btn { display: none; }
@media (max-width: 767px) { .btn.mobile-menu-btn { display: inline-flex; margin-left: auto; } }
